#!/usr/bin/env python3
# ===== File: build-face-bundle.py — regenerates tf-face.bundle.js from the real component =====
# Run from the repository root: python3 mockups/chat-20261024/shared/build-face-bundle.py
import pathlib
import re

WWW = pathlib.Path("tentaflow-core/www/js")
OUT = pathlib.Path(__file__).with_name("tf-face.bundle.js")
SOURCES = ["data/face-data.js", "data/face-edges.js", "components/tf-face.js"]

parts = [
    "// ===== File: tf-face.bundle.js — classic-script build of the real tf-face component for the chat mockup =====\n",
    "// Generated by build-face-bundle.py from data/face-data.js, data/face-edges.js and components/tf-face.js:\n",
    "// imports/exports stripped, one IIFE, so the mockup also works from file:// (ES modules are blocked there).\n",
    "(function () {\n",
]
for name in SOURCES:
    text = (WWW / name).read_text()
    text = re.sub(r"^import\s*\{[^}]*\}\s*from\s*[^;]+;\n", "", text, flags=re.M)
    text = re.sub(r"^export \{[^}]*\};\n", "", text, flags=re.M)
    text = re.sub(r"^export (const|function|class) ", r"\1 ", text, flags=re.M)
    parts.append(f"// --- {name} ---\n")
    parts.append(text)
parts.append("})();\n")
OUT.write_text("".join(parts))
